@SpringBootTest
@Testcontainers
class PedidoRepositoryIT {

    @Container
    @ServiceConnection
    static PostgreSQLContainer<?> postgres = new PostgreSQLContainer<>("postgres:16-alpine");

    @Autowired PedidoRepository repository;

    @Test
    void deveBuscarPedidosPagos() {
