// Consumidor (Pact JVM + JUnit 5)
@Pact(consumer = "checkout", provider = "estoque")
V4Pact estoqueDisponivel(PactDslWithProvider builder) {
    return builder
        .given("produto LIV-01 com estoque")
        .uponReceiving("consulta de estoque")
            .path("/estoque/LIV-01").method("GET")
        .willRespondWith()
            .status(200)
            .body(new PactDslJsonBody().stringType("sku", "LIV-01").integerType("quantidade", 10))
        .toPact(V4Pact.class);
}

@AnalyzeClasses(packages = "com.loja")
class ArquiteturaTest {

    @ArchTest
    static final ArchRule camadas = layeredArchitecture().consideringAllDependencies()
        .layer("Controller").definedBy("..controller..")
        .layer("Service").definedBy("..service..")
        .layer("Repository").definedBy("..repository..")
        .whereLayer("Controller").mayNotBeAccessedByAnyLayer()
        .whereLayer("Repository").mayOnlyBeAccessedByLayers("Service");

    @ArchTest
    static final ArchRule dominioSemSpring = noClasses().that().resideInAPackage("..domain..")
        .should().dependOnClassesThat().resideInAPackage("org.springframework..");
}

